import { Input, Snapshot, Update } from '../bebop/generated.mjs'
import { KINDS, STANCES } from '../workloads.mjs'

export const name = 'bebop'
export const pkg = 'bebop'
export const kind = 'schema'
export const notes =
  'code generated by bebopc 3.2.3 from bebop/messages.bop; struct for the dense records, message for the ' +
  'optional fields (a byte per field present); enums from 1, as Bebop asks; t as uint64 (BigInt)'

const KIND_VALUE = Object.fromEntries(KINDS.map((value, i) => [value, i + 1]))
const STANCE_VALUE = Object.fromEntries(STANCES.map((value, i) => [value, i + 1]))

const snapshot = {
  encode: message =>
    Snapshot.encode({
      t: BigInt(message.t),
      entities: message.entities.map(entity => ({
        id: entity.id,
        name: entity.name,
        kind: KIND_VALUE[entity.kind],
        x: entity.x,
        y: entity.y,
        rot: entity.rot,
        health: entity.health,
        maxHealth: entity.maxHealth,
        mana: entity.mana,
        level: entity.level,
        alive: entity.alive,
      })),
    }),
  decode: data => Snapshot.decode(data),
  view: decoded => ({
    t: Number(decoded.t),
    entities: decoded.entities.map(entity => ({ ...entity, kind: KINDS[entity.kind - 1] })),
  }),
}

const update = {
  encode: message =>
    Update.encode({
      t: BigInt(message.t),
      ack: message.ack,
      updates: message.updates.map(change =>
        change.stance === undefined ? change : { ...change, stance: STANCE_VALUE[change.stance] },
      ),
    }),
  decode: data => Update.decode(data),
  view: decoded => ({
    t: Number(decoded.t),
    ack: decoded.ack,
    updates: decoded.updates.map(change =>
      change.stance === undefined ? { ...change } : { ...change, stance: STANCES[change.stance - 1] },
    ),
  }),
}

const input = {
  // under 256 bytes the runtime returns a view of the buffer it writes every message in
  encode: message =>
    Input.encode({
      seq: message.seq,
      t: BigInt(message.t),
      x: message.x,
      y: message.y,
      vx: message.vx,
      vy: message.vy,
      rot: message.rot,
      zone: message.zone,
      actions: message.actions,
    }).slice(),
  decode: data => Input.decode(data),
  view: ({ seq, t, x, y, vx, vy, rot, zone, actions }) => ({
    seq,
    t: Number(t),
    x,
    y,
    vx,
    vy,
    rot,
    zone,
    actions: actions.map(action => ({ ...action })),
  }),
}

export const workloads = { snapshot: () => snapshot, update: () => update, input: () => input }
